import{_ as p,W as o,s as l,u,ah as d,I as i,w as e,Z as n,A as t}from"./chunks/framework.B4JzB-Td.js";import"./chunks/theme.Xs8fIzCW.js";const f=JSON.parse('{"title":"如何在 Linux 中禁用内置摄像头 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中禁用内置摄像头 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 Linux 中禁用内置摄像头 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中禁用内置摄像头 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180531 How To Disable Built-in Webcam In Linux","title":"如何在 Linux 中禁用内置摄像头","tag":"201806"},"relativePath":"201806/20180531 How To Disable Built-in Webcam In Linux.md","filePath":"[post].md"}'),c={name:"201806/20180531 How To Disable Built-in Webcam In Linux.md"};function b(r,s,v,h,m,g){const a=o("Link");return u(),l("div",null,[s[15]||(s[15]=d(`<h1 id="如何在-linux-中禁用内置摄像头" tabindex="-1">如何在 Linux 中禁用内置摄像头 <a class="header-anchor" href="#如何在-linux-中禁用内置摄像头" aria-label="Permalink to 如何在 Linux 中禁用内置摄像头">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2015/08/webcam-2-720x340.jpg" alt=""></p><p>今天，我们将看到如何禁用未使用的内置网络摄像头或外置摄像头，以及如何在 Linux 中需要时启用它。禁用网络摄像头可以在很多方面为你提供帮助。你可以防止恶意软件控制你的集成摄像头，并监视你和你的家庭。我们已经阅读过无数的故事，一些黑客可以在你不知情的情况下使用你的摄像头监视你。通过黑客攻击你的网络摄像头，用户可以在线共享你的私人照片和视频。可能有很多原因。如果你想知道如何禁用笔记本电脑或台式机中的网络摄像头，那么你很幸运。这个简短的教程将告诉你如何做。请继续阅读。</p><p>我在 Arch Linux 和 Ubuntu 上测试了这个指南。它的工作原理如下所述。我希望这也可以用在其他 Linux 发行版上。</p><h3 id="在-linux-中禁用内置摄像头" tabindex="-1">在 Linux 中禁用内置摄像头 <a class="header-anchor" href="#在-linux-中禁用内置摄像头" aria-label="Permalink to 在 Linux 中禁用内置摄像头">​</a></h3><p>首先，使用如下命令找到网络摄像头驱动：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo lsmod | grep uvcvideo</span></span></code></pre></div><p>示例输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uvcvideo 114688 1</span></span>
<span class="line"><span>videobuf2_vmalloc 16384 1 uvcvideo</span></span>
<span class="line"><span>videobuf2_v4l2 28672 1 uvcvideo</span></span>
<span class="line"><span>videobuf2_common 53248 2 uvcvideo,videobuf2_v4l2</span></span>
<span class="line"><span>videodev 208896 4 uvcvideo,videobuf2_common,videobuf2_v4l2</span></span>
<span class="line"><span>media 45056 2 uvcvideo,videodev</span></span>
<span class="line"><span>usbcore 286720 9 uvcvideo,usbhid,usb_storage,ehci_hcd,ath3k,btusb,uas,ums_realtek,ehci_pci</span></span></code></pre></div><p>这里，<strong>uvcvideo</strong> 是我的网络摄像头驱动。</p><p>现在，让我们禁用网络摄像头。</p><p>为此，请编辑以下文件（如果文件不存在，只需创建它）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo nano /etc/modprobe.d/blacklist.conf</span></span></code></pre></div><p>添加以下行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>##Disable webcam.</span></span>
<span class="line"><span>blacklist uvcvideo</span></span></code></pre></div><p><code>##Disable webcam</code> 这行不是必需的。为了便于理解，我添加了它。</p><p>保存并退出文件。重启系统以使更改生效。</p><p>要验证网络摄像头是否真的被禁用，请打开任何即时通讯程序或网络摄像头软件，如 Cheese 或 Guvcview。你会看到如下的空白屏幕。</p><p>Cheese 输出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2015/08/cheese.jpg" alt=""></p><p>Guvcview 输出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2015/08/guvcview.jpg" alt=""></p><p>看见了么？网络摄像头被禁用而无法使用。</p><p>要启用它，请编辑：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo nano /etc/modprobe.d/blacklist.conf</span></span></code></pre></div><p>注释掉你之前添加的行。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>##Disable webcam.</span></span>
<span class="line"><span>#blacklist uvcvideo</span></span></code></pre></div><p>保存并关闭文件。然后，重启计算机以启用网络摄像头。</p><p>这样够了吗？不。为什么？如果有人可以远程访问你的系统，他们可以轻松启用网络摄像头。所以，在不使用时用胶带覆盖它或者拔掉相机或者在 BIOS 中禁用它是一个不错的主意。此方法不仅用于禁用内置摄像头，还用于外部网络摄像头。</p><p>就是这些了。希望对你有用。还有更好的东西。敬请关注！</p><p>干杯!</p><hr>`,32)),i("p",null,[s[1]||(s[1]=e("via: ")),n(a,{href:"https://www.ostechnix.com/how-to-disable-built-in-webcam-in-ubuntu/"},{default:t(()=>s[0]||(s[0]=[e("https://www.ostechnix.com/how-to-disable-built-in-webcam-in-ubuntu/")])),_:1})]),i("p",null,[s[6]||(s[6]=e("作者：")),n(a,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>s[2]||(s[2]=[e("SK")])),_:1}),s[7]||(s[7]=e(" 选题：")),n(a,{href:"https://github.com/lujun9972"},{default:t(()=>s[3]||(s[3]=[e("lujun9972")])),_:1}),s[8]||(s[8]=e(" 译者：")),n(a,{href:"https://github.com/geekpi"},{default:t(()=>s[4]||(s[4]=[e("geekpi")])),_:1}),s[9]||(s[9]=e(" 校对：")),n(a,{href:"https://github.com/wxy"},{default:t(()=>s[5]||(s[5]=[e("wxy")])),_:1})]),i("p",null,[s[12]||(s[12]=e("本文由 ")),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>s[10]||(s[10]=[e("LCTT")])),_:1}),s[13]||(s[13]=e(" 原创编译，")),n(a,{href:"https://linux.cn/"},{default:t(()=>s[11]||(s[11]=[e("Linux中国")])),_:1}),s[14]||(s[14]=e(" 荣誉推出"))])])}const k=p(c,[["render",b]]);export{f as __pageData,k as default};
